using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — resolves any type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probe without throwing
if (webOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? probed))
{
    Console.WriteLine($"TryGetTypeInfo<Person> → succeeded, Type = {probed!.Type.Name}");
}

// Now demonstrate a case where TryGetTypeInfo returns false:
// use a source-gen context that only knows about Person.
var strictOptions = new JsonSerializerOptions
{
    TypeInfoResolver = SmallContext.Default
};

if (strictOptions.TryGetTypeInfo<int>(out _))
{
    Console.WriteLine("TryGetTypeInfo<int> → succeeded (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int> → not available (no exception thrown)");
}

